-- Errata reading for H02: CKD per config/agere/definitions.json chronic_kidney_disease (N18 stages incl. stage 5/ESRD, diabetic kidney disease, hypertensive CKD I12/I13, CKD labels); any potassium > 5.0.
WITH ckd AS MATERIALIZED ( SELECT DISTINCT patient FROM records WHERE stream='conditions' AND ( substr(json_extract(payload,'$.icd10'),1,3)='N18' OR json_extract(payload,'$.snomed') IN ('431855005','431856006','433144002','431857002','433146000','46177005','127013003') OR substr(json_extract(payload,'$.icd10'),1,3) IN ('I12','I13') OR (substr(json_extract(payload,'$.icd10'),1,3) BETWEEN 'E08' AND 'E13' AND substr(json_extract(payload,'$.icd10'),5,1)='2') OR lower(json_extract(payload,'$.description')) LIKE '%chronic kidney disease%' OR json_extract(payload,'$.description') LIKE '%CKD%' OR lower(json_extract(payload,'$.description')) LIKE '%end-stage renal%' OR lower(json_extract(payload,'$.description')) LIKE '%kidney due to diabetes%') ), k AS MATERIALIZED ( SELECT patient,json_extract(payload,'$.value') AS v FROM records WHERE stream='labs' AND json_extract(payload,'$.name')='Potassium' AND json_extract(payload,'$.unit') IN ('mmol/L','mEq/L') AND json_type(payload,'$.value') IN ('integer','real') ) SELECT DISTINCT ckd.patient AS patient_id FROM ckd JOIN k USING(patient) WHERE k.v>5.0 ORDER BY patient_id;
